package system

func addAccountDeletionOpenAPI(components, paths map[string]any) {
	schemas := components["schemas"].(map[string]any)
	uuid := map[string]any{"type": "string", "format": "uuid"}
	stringType := map[string]any{"type": "string"}
	schemas["AccountDeletionSuccessor"] = map[string]any{"type": "object", "additionalProperties": false, "required": []string{"team_id", "user_id"}, "properties": map[string]any{"team_id": uuid, "user_id": uuid}}
	schemas["AccountDeletionChoices"] = map[string]any{"type": "object", "additionalProperties": false, "properties": map[string]any{"successors": map[string]any{"type": "array", "maxItems": 512, "items": map[string]any{"$ref": "#/components/schemas/AccountDeletionSuccessor"}}, "close_team_ids": map[string]any{"type": "array", "maxItems": 512, "items": uuid}}}
	schemas["AccountDeletionConfirmation"] = map[string]any{"type": "object", "additionalProperties": false, "required": []string{"attempt_id", "consequence_hash", "confirm"}, "properties": map[string]any{"attempt_id": stringType, "consequence_hash": map[string]any{"type": "string", "pattern": "^[0-9a-f]{64}$"}, "confirm": map[string]any{"const": true}}}
	schemas["AccountDeletionSite"] = map[string]any{"type": "object", "required": []string{"id", "domain", "owned"}, "properties": map[string]any{"id": uuid, "domain": stringType, "owned": map[string]any{"type": "boolean"}}}
	schemas["AccountDeletionOwner"] = map[string]any{"type": "object", "required": []string{"id", "email"}, "properties": map[string]any{"id": uuid, "email": map[string]any{"type": "string", "format": "email"}}}
	schemas["AccountDeletionBlocker"] = map[string]any{"type": "object", "required": []string{"code"}, "properties": map[string]any{"code": map[string]any{"type": "string", "enum": []string{"last_operator", "ownership_transfer_required", "successor_required", "invalid_successor", "closure_policy"}}, "team_id": uuid}}
	schemas["AccountDeletionTeam"] = map[string]any{"type": "object", "required": []string{"id", "name", "action", "member_count", "closure_allowed", "sites", "eligible_successors", "cancellation_required"}, "properties": map[string]any{"id": uuid, "name": stringType, "action": map[string]any{"type": "string", "enum": []string{"leave", "reparent", "close"}}, "member_count": map[string]any{"type": "integer"}, "closure_allowed": map[string]any{"type": "boolean"}, "sites": map[string]any{"type": "array", "items": map[string]any{"$ref": "#/components/schemas/AccountDeletionSite"}}, "eligible_successors": map[string]any{"type": "array", "items": map[string]any{"$ref": "#/components/schemas/AccountDeletionOwner"}}, "successor_id": uuid, "cancellation_required": map[string]any{"type": "boolean"}, "billing_fingerprint": stringType}}
	schemas["AccountDeletionPreparation"] = map[string]any{"type": "object", "required": []string{"teams", "blockers", "attempt_id", "expires_at", "purpose", "phase", "consequence_hash", "reauth", "retention"}, "properties": map[string]any{"teams": map[string]any{"type": "array", "items": map[string]any{"$ref": "#/components/schemas/AccountDeletionTeam"}}, "blockers": map[string]any{"type": "array", "items": map[string]any{"$ref": "#/components/schemas/AccountDeletionBlocker"}}, "attempt_id": stringType, "expires_at": map[string]any{"type": "string", "format": "date-time"}, "purpose": map[string]any{"const": "delete-current-account"}, "phase": map[string]any{"type": "string", "enum": []string{"blocked", "prepared", "authorized", "removing", "complete"}}, "consequence_hash": stringType, "reauth": map[string]any{"type": "object", "properties": map[string]any{"return_path": stringType, "methods": map[string]any{"type": []string{"array", "null"}, "items": stringType}, "verified": map[string]any{"type": "boolean"}}}, "retention": map[string]any{"type": "object", "properties": map[string]any{"billing_records": map[string]any{"const": true}, "cancellation": map[string]any{"const": "period_end"}}}}}
	schemas["AccountDeletionError"] = map[string]any{"type": "object", "required": []string{"error"}, "properties": map[string]any{"error": map[string]any{"type": "object", "required": []string{"code", "message"}, "properties": map[string]any{"code": stringType, "message": stringType}}}}
	schemas["AccountDeletionProviderRevocation"] = map[string]any{"type": "object", "additionalProperties": false, "required": []string{"provider", "status"}, "properties": map[string]any{"provider": map[string]any{"const": "apple"}, "status": map[string]any{"type": "string", "enum": []string{"revoked", "manual_revocation_required"}}}}
	schemas["AccountDeletionResult"] = map[string]any{"type": "object", "required": []string{"status", "provider_revocations"}, "properties": map[string]any{"status": map[string]any{"const": "deleted"}, "provider_revocations": map[string]any{"type": "array", "items": map[string]any{"$ref": "#/components/schemas/AccountDeletionProviderRevocation"}}}}
	errors := func() map[string]any {
		return map[string]any{"400": jsonRefResp("Explicit confirmation or valid JSON required", "#/components/schemas/AccountDeletionError"), "401": jsonRefResp("Current human session and fresh purpose-bound proof required", "#/components/schemas/AccountDeletionError"), "403": jsonRefResp("Same-origin browser request required", "#/components/schemas/AccountDeletionError"), "409": jsonRefResp("Ownership, policy or immutable consequences changed; prepare again", "#/components/schemas/AccountDeletionError"), "503": jsonRefResp("Proof, tenant storage, or provider unavailable; retain and retry the authorized intent", "#/components/schemas/AccountDeletionError")}
	}
	prepareResponses := errors()
	prepareResponses["200"] = jsonRefResp("Consequences and blockers; only an unblocked plan has an attempt", "#/components/schemas/AccountDeletionPreparation")
	paths["/api/user/account/deletion/prepare"] = map[string]any{"post": op([]string{"User"}, "Prepare current account deletion", "No deletion occurs. Choose an existing owner from each surviving team whose site ownership must change. Only explicitly selected, truly solo Cloud teams may close. Last instance owners must hand over operator authority.", secCookie(), nil, jsonBody(map[string]any{"$ref": "#/components/schemas/AccountDeletionChoices"}), prepareResponses)}
	statusResponses := errors()
	statusResponses["200"] = jsonRefResp("Immutable consequences and fresh-proof status; read only", "#/components/schemas/AccountDeletionPreparation")
	statusResponses["404"] = jsonRefResp("Attempt unavailable for current user", "#/components/schemas/AccountDeletionError")
	paths["/api/user/account/deletion/{attempt_id}"] = map[string]any{"get": op([]string{"User"}, "Read current account deletion preparation", "Reading an attempt never authorizes or executes deletion.", secCookie(), []any{map[string]any{"name": "attempt_id", "in": "path", "required": true, "schema": stringType}}, nil, statusResponses)}
	finalResponses := errors()
	finalResponses["200"] = jsonRefResp("Account removed; clients must clear credentials/cache and show any manual provider revocation guidance", "#/components/schemas/AccountDeletionResult")
	paths["/api/user/account"] = map[string]any{"delete": op([]string{"User"}, "Delete current human account", "Requires explicit approval plus single-use attempt/consequence/current-user/session-JTI-bound proof after real primary login and configured MFA. API, OAuth and embed credentials are rejected even alongside a cookie. Rechecks ownership and billing before execution. Shared teams, analytics and team credentials survive. Explicit solo Cloud closure removes analytics immediately after verified cancellation at period end; no refund or immediate paid-period termination occurs. Required billing/legal records remain. This operation is a resumable lifecycle, not a cross-database/provider transaction.", secCookie(), nil, jsonBody(map[string]any{"$ref": "#/components/schemas/AccountDeletionConfirmation"}), finalResponses)}
}
